//! The acceptance checks of the joint SPX and VIX calibration of the quadratic rough Heston
//! model (#970).
//!
//! Both legs are generated by the model itself on the grid and seed of the fit: the SPX leg by
//! `price_surface_quadratic_rough_heston`, the VIX leg by `price_vix_quadratic_rough_heston`
//! on a single-maturity grid of the same step, which draws the same paths as the fit's grid
//! because every segment has the same step. The objective is then zero at the truth up to the
//! implied volatility solver's tolerance. No parameter set here comes from either paper.

use optionstratlib_core::model::Positive;
use optionstratlib_core::model::decimal::decimal_to_f64;
use optionstratlib_core::model::types::OptionStyle;
use optionstratlib_core::pos_or_panic;
use optionstratlib_simulation::error::QuadraticRoughHestonError;
use optionstratlib_simulation::simulation::{
    QuadraticRoughHestonCalibrationConfig, QuadraticRoughHestonFreeParameters,
    QuadraticRoughHestonGrid, QuadraticRoughHestonKernel, QuadraticRoughHestonMonteCarloConfig,
    QuadraticRoughHestonParams, QuadraticRoughHestonQuote, QuadraticRoughHestonSurfacePoint,
    QuadraticRoughHestonVix, QuadraticRoughHestonVixPayoff, QuadraticRoughHestonVixQuote,
    calibrate_quadratic_rough_heston, calibrate_quadratic_rough_heston_joint,
    price_surface_quadratic_rough_heston, price_vix_quadratic_rough_heston,
};
use rust_decimal::Decimal;
use rust_decimal_macros::dec;
use std::num::{NonZeroU64, NonZeroUsize};

const SEED: u64 = 970;
const PATHS: usize = 2_000;
/// The step of every segment, in years.
const STEP: f64 = 0.01;

fn params(
    a: Decimal,
    b: Decimal,
    c: Decimal,
    lambda: Decimal,
    eta: Decimal,
) -> QuadraticRoughHestonParams {
    let kernel = QuadraticRoughHestonKernel::try_new(dec!(0.6), 2, dec!(5)).unwrap();
    QuadraticRoughHestonParams::try_new(
        a,
        b,
        c,
        lambda,
        eta,
        kernel,
        vec![dec!(-0.1), dec!(-0.2)],
        Positive::HUNDRED,
    )
    .unwrap()
}

fn truth() -> QuadraticRoughHestonParams {
    params(dec!(0.4), dec!(0.1), dec!(0.02), dec!(1.5), dec!(0.8))
}

fn start() -> QuadraticRoughHestonParams {
    params(dec!(0.6), dec!(0.05), dec!(0.012), dec!(1.0), dec!(1.1))
}

fn monte_carlo() -> QuadraticRoughHestonMonteCarloConfig {
    QuadraticRoughHestonMonteCarloConfig {
        paths: NonZeroUsize::new(PATHS).unwrap(),
        max_step: Positive::new(STEP).unwrap(),
        seed: SEED,
    }
}

fn config() -> QuadraticRoughHestonCalibrationConfig {
    QuadraticRoughHestonCalibrationConfig {
        monte_carlo: monte_carlo(),
        max_iterations: NonZeroU64::new(4_000).unwrap(),
        tolerance: pos_or_panic!(1e-6),
        initial_step: pos_or_panic!(0.1),
    }
}

fn spx_quotes() -> Vec<QuadraticRoughHestonQuote> {
    let mut points = Vec::new();
    for maturity in [0.1, 0.25, 0.5] {
        for strike in [85.0, 95.0, 100.0, 105.0, 115.0] {
            points.push(QuadraticRoughHestonSurfacePoint {
                maturity: Positive::new(maturity).unwrap(),
                strike: Positive::new(strike).unwrap(),
            });
        }
    }
    price_surface_quadratic_rough_heston(&truth(), &points, &monte_carlo())
        .unwrap()
        .into_iter()
        .map(|quote| QuadraticRoughHestonQuote {
            maturity: quote.maturity,
            strike: quote.strike,
            implied_volatility: quote.implied_volatility.unwrap(),
            weight: Positive::ONE,
        })
        .collect()
}

/// The future and three calls at two of the SPX maturities, priced by the model.
fn vix_quotes(weight: Positive) -> Vec<QuadraticRoughHestonVixQuote> {
    let model = truth();
    let window = QuadraticRoughHestonVix::thirty_days(&model)
        .unwrap()
        .window();
    let mut quotes = Vec::new();
    for (maturity, steps) in [(dec!(0.25), 25), (dec!(0.5), 50)] {
        let grid = QuadraticRoughHestonGrid::try_new(maturity, steps).unwrap();
        let mut payoffs = vec![QuadraticRoughHestonVixPayoff::Future];
        for strike in [12.0, 16.0, 20.0] {
            payoffs.push(QuadraticRoughHestonVixPayoff::Vanilla {
                style: OptionStyle::Call,
                strike: Positive::new(strike).unwrap(),
            });
        }
        for payoff in payoffs {
            let estimate = price_vix_quadratic_rough_heston(
                &model,
                &grid,
                window,
                payoff,
                NonZeroUsize::new(PATHS).unwrap(),
                SEED,
            )
            .unwrap();
            quotes.push(QuadraticRoughHestonVixQuote {
                maturity: Positive::new_decimal(maturity).unwrap(),
                payoff,
                price: Positive::new_decimal(estimate.price()).unwrap(),
                weight,
            });
        }
    }
    quotes
}

fn relative_error(actual: Decimal, expected: Decimal) -> f64 {
    let (actual, expected) = (
        decimal_to_f64(actual).unwrap(),
        decimal_to_f64(expected).unwrap(),
    );
    (actual - expected).abs() / expected.abs()
}

/// From a start 30% to 50% away, the joint fit recovers `(a, b, c, lambda, eta)` from the
/// model's own SPX surface and VIX quotes, and every VIX residual vanishes.
#[test]
fn test_joint_calibration_recovers_the_model_parameters_from_both_legs() {
    const RELATIVE_TOLERANCE: f64 = 1e-3;
    let fit = calibrate_quadratic_rough_heston_joint(
        &spx_quotes(),
        &vix_quotes(Positive::ONE),
        &start(),
        QuadraticRoughHestonFreeParameters::MODEL,
        &config(),
    )
    .unwrap();
    let (truth, fitted) = (truth(), fit.params().clone());
    for (name, actual, expected) in [
        ("a", fitted.a(), truth.a()),
        ("b", fitted.b(), truth.b()),
        ("c", fitted.c(), truth.c()),
        ("lambda", fitted.lambda(), truth.lambda()),
        ("eta", fitted.eta(), truth.eta()),
    ] {
        assert!(
            relative_error(actual, expected) < RELATIVE_TOLERANCE,
            "{name}: {actual} against {expected}, rmse {}, {} iterations",
            fit.rmse(),
            fit.iterations()
        );
    }
    assert!(fit.rmse().to_dec() < dec!(1e-5), "{}", fit.rmse());
    assert!(fit.spx_rmse().unwrap().to_dec() < dec!(1e-5));
    assert!(fit.vix_rmse().unwrap().to_dec() < dec!(1e-5));
    assert_eq!(fit.vix_quotes().len(), 8);
    for vix_fit in fit.vix_quotes() {
        assert!(vix_fit.residual.abs() < dec!(1e-5), "{vix_fit:?}");
        assert!(vix_fit.model_price > Decimal::ZERO);
    }
    let steps: Vec<usize> = fit.grid().iter().map(|segment| segment.steps).collect();
    assert_eq!(steps, vec![10, 15, 25]);
}

/// With every VIX weight zero and the VIX maturities among the SPX ones, the joint fit is the
/// SPX-only fit on the same quotes, seed and grid, and still reports the VIX quotes.
#[test]
fn test_joint_calibration_with_zero_vix_weight_is_the_spx_fit() {
    let free = QuadraticRoughHestonFreeParameters {
        a: true,
        c: true,
        ..Default::default()
    };
    let spx = spx_quotes();
    let spx_only = calibrate_quadratic_rough_heston(&spx, &start(), free, &config()).unwrap();
    let joint = calibrate_quadratic_rough_heston_joint(
        &spx,
        &vix_quotes(Positive::ZERO),
        &start(),
        free,
        &config(),
    )
    .unwrap();
    assert_eq!(joint.params(), spx_only.params());
    assert_eq!(joint.quotes(), spx_only.quotes());
    assert_eq!(joint.objective(), spx_only.objective());
    assert_eq!(joint.rmse(), spx_only.rmse());
    assert_eq!(joint.iterations(), spx_only.iterations());
    assert_eq!(joint.grid(), spx_only.grid());
    assert_eq!(joint.vix_quotes().len(), 8);
    assert_eq!(joint.vix_rmse(), None);
    assert_eq!(spx_only.vix_quotes().len(), 0);
    assert_eq!(spx_only.spx_rmse(), Some(spx_only.rmse()));
}

/// VIX quotes alone are a valid fit, and invalid inputs return typed errors.
#[test]
fn test_joint_calibration_vix_only_and_invalid_inputs() {
    let vix = vix_quotes(Positive::ONE);
    let free = QuadraticRoughHestonFreeParameters {
        c: true,
        ..Default::default()
    };
    let fit = calibrate_quadratic_rough_heston_joint(&[], &vix, &start(), free, &config()).unwrap();
    assert_eq!(fit.spx_rmse(), None);
    assert!(fit.vix_rmse().is_some());

    assert!(matches!(
        calibrate_quadratic_rough_heston_joint(
            &[],
            &vix_quotes(Positive::ZERO),
            &start(),
            free,
            &config()
        ),
        Err(QuadraticRoughHestonError::NoQuotes)
    ));
    let mut zero_maturity = vix.clone();
    zero_maturity[2].maturity = Positive::ZERO;
    assert!(matches!(
        calibrate_quadratic_rough_heston_joint(&[], &zero_maturity, &start(), free, &config()),
        Err(QuadraticRoughHestonError::InvalidQuote {
            index: 2,
            reason: "the vix maturity must be positive"
        })
    ));
}
